import Page8 from './pages/Page8.jsx';
import Page9 from './pages/Page9.jsx';
import Page10 from './pages/Page10.jsx';
import Page11 from './pages/Page11.jsx';
const pages={"demo-accounting-1":Page0,"demo-accounting-1-about":Page1,"demo-accounting-1-article":Page2,"demo-accounting-1-blog":Page3,"demo-accounting-1-calculators":Page4,"demo-accounting-1-contact":Page5,"demo-accounting-1-pricing":Page6,"demo-accounting-1-service":Page7,"demo-accounting-1-services":Page8,"demo-accounting-1-tax-calendar":Page9,"demo-accounting-1-team":Page10,"demo-accounting-1-who-we-help":Page11};
export default function App(){
const [page,setPage]=useState(()=>new URLSearchParams(location.hash.slice(1)).get('page')||"demo-accounting-1");
useEffect(()=>{const change=()=>setPage(new URLSearchParams(location.hash.slice(1)).get('page')||"demo-accounting-1");const navigate=e=>{const a=e.target.closest('a[href]');const href=a?.getAttribute('href');if(!href?.startsWith('#page='))return;const next=new URLSearchParams(href.slice(1)).get('page');if(!pages[next])return;e.preventDefault();e.stopPropagation();setPage(next);try{if(location.protocol!=='about:')history.pushState(null,'',href)}catch{}};document.addEventListener('click',navigate,true);window.addEventListener('hashchange',change);window.addEventListener('popstate',change);return()=>{document.removeEventListener('click',navigate,true);window.removeEventListener('hashchange',change);window.removeEventListener('popstate',change)}},[]);
useTemplateRuntime(page);const Page=pages[page]||Page0;return <div id='template-page' key={page}><Page/></div>;
}

